-- Base de riscos ocupacionais (operador de empilhadeira) para todos os clientes.
-- Idempotente: só insere o que o cliente ainda não tem com o mesmo nome.
INSERT INTO "hazards" ("id","tenantId","category","name","sourceCircumstances","damagePotential","adminMeasures","updatedAt")
SELECT 'base_' || md5(t."id" || b."name"), t."id", b."category", b."name", b."fonte", b."danos", b."medidas", CURRENT_TIMESTAMP
FROM "tenants" t
CROSS JOIN (VALUES
  ('FISICO'::"RiskCategory", 'Ruído contínuo ou intermitente', 'Motor, buzina e circulação de empilhadeiras e outros equipamentos.', 'Desconforto, zumbido e possível perda auditiva, conforme intensidade e duração.', 'Avaliar a exposição; manter motor e componentes conservados; reduzir fontes de ruído e adotar proteção auditiva quando indicada.'),
  ('FISICO'::"RiskCategory", 'Vibração de corpo inteiro', 'Condução do equipamento, sobretudo em pisos irregulares, com impactos ou durante períodos prolongados.', 'Desconforto, fadiga e dores musculoesqueléticas.', 'Conservar pneus, assento e suspensão; manter o piso em boas condições; ajustar velocidade e organização do tempo de operação.'),
  ('FISICO'::"RiskCategory", 'Calor / desconforto térmico', 'Operação em área externa, ambiente quente ou cabine sem proteção térmica, se aplicável.', 'Desconforto térmico, fadiga e mal-estar.', 'Avaliar o ambiente; prever hidratação e pausas; considerar vestimenta e proteção compatíveis.'),
  ('FISICO'::"RiskCategory", 'Frio', 'Operação em câmara fria ou ambiente refrigerado, se aplicável.', 'Desconforto, redução de destreza e efeitos relacionados à exposição ao frio.', 'Avaliar tempo de exposição; fornecer vestimenta adequada e organizar pausas em local protegido.'),
  ('QUIMICO'::"RiskCategory", 'Gases e fumos de combustão', 'Empilhadeira a GLP, diesel ou gasolina, principalmente em ambientes fechados ou pouco ventilados.', 'Irritação, dor de cabeça, tontura, náusea e efeitos respiratórios, conforme o agente e a exposição.', 'Garantir ventilação; manter motor regulado; priorizar equipamento elétrico quando tecnicamente adequado; avaliar e monitorar a exposição.'),
  ('QUIMICO'::"RiskCategory", 'Combustíveis, óleos e lubrificantes', 'Abastecimento, vazamentos, inspeção ou manutenção, quando realizados pelo trabalhador.', 'Irritação ou dermatite; efeitos adicionais dependem do produto.', 'Seguir procedimento; consultar rótulo e FDS; prevenir contato e derramamentos; utilizar proteção definida para o produto.'),
  ('QUIMICO'::"RiskCategory", 'Eletrólito e gases de bateria', 'Recarga, manutenção ou troca de bateria chumbo-ácido, se aplicável.', 'Irritação ou queimadura química; risco adicional durante carregamento.', 'Realizar em área apropriada e ventilada; impedir fontes de ignição; seguir procedimento e usar proteção especificada.'),
  ('QUIMICO'::"RiskCategory", 'Poeiras / aerodispersóides', 'Circulação em áreas com poeira suspensa de materiais, embalagens ou vias não pavimentadas.', 'Irritação ocular ou respiratória, conforme composição e exposição.', 'Controlar geração e dispersão; manter limpeza; avaliar exposição e definir proteção quando necessária.'),
  ('BIOLOGICO'::"RiskCategory", 'Microrganismos e parasitas infecciosos e seus tóxicos', 'Contato ocupacional com resíduos, materiais contaminados, pragas ou áreas específicas, quando houver.', 'Infecções, alergias ou outros agravos, conforme agente e via de exposição.', 'Confirmar a presença do perigo; manter higiene e controle de pragas; adotar procedimentos e proteção compatíveis.'),
  ('ERGONOMICO'::"RiskCategory", 'Postura sentada prolongada', 'Permanência na posição de condução durante períodos extensos.', 'Fadiga e desconforto em costas, pescoço e membros.', 'Ajustar banco, apoio e comandos; organizar pausas e alternância de tarefas conforme avaliação ergonômica.'),
  ('ERGONOMICO'::"RiskCategory", 'Movimentos repetitivos e exigência visual', 'Uso frequente de comandos, manobras e observação contínua do trajeto, carga e pedestres.', 'Fadiga muscular ou visual e desconforto.', 'Adequar organização do trabalho, pausas, iluminação, campo de visão e posicionamento dos comandos.'),
  ('ERGONOMICO'::"RiskCategory", 'Força, torção ou esforço no acesso ao equipamento', 'Subir e descer repetidamente; movimentar manualmente acessórios ou materiais, quando aplicável.', 'Fadiga, distensões e desconforto musculoesquelético.', 'Manter degraus e alças em boas condições; usar pontos de apoio; evitar movimentação manual desnecessária.'),
  ('ERGONOMICO'::"RiskCategory", 'Movimentação manual de cargas', 'Carga, descarga, ajuste ou reposicionamento manual de materiais, se fizer parte da função.', 'Dores, distensões e lesões musculoesqueléticas.', 'Reduzir manuseio manual; usar meios mecânicos; avaliar peso, frequência, pega e distância de transporte.'),
  ('ERGONOMICO'::"RiskCategory", 'Alta demanda cognitiva / múltiplas tarefas', 'Conduzir, controlar a carga, observar pedestres e responder a sinais ou instruções simultaneamente.', 'Fadiga mental, distração e aumento da possibilidade de erro.', 'Organizar fluxo e comunicação; reduzir interrupções; planejar rotas e evitar exigências incompatíveis com condução segura.'),
  ('ERGONOMICO'::"RiskCategory", 'Ritmo intenso, pressão de tempo ou falta de suporte', 'Metas, exigência de tempo, baixa autonomia, jornadas prolongadas ou suporte insuficiente, quando presentes.', 'Estresse, fadiga, redução da atenção e possível aumento de incidentes.', 'Avaliar a organização do trabalho com participação dos trabalhadores; ajustar metas, pausas, efetivo e suporte.'),
  ('ACIDENTE'::"RiskCategory", 'Circulação de veículos - colisão ou abalroamento', 'Corredores, docas, cruzamentos, áreas estreitas ou circulação junto a outros veículos e máquinas.', 'Contusões, fraturas, esmagamento e lesões graves.', 'Segregar rotas; sinalizar cruzamentos; controlar velocidade; manter visibilidade e regras de circulação.'),
  ('ACIDENTE'::"RiskCategory", 'Atropelamento', 'Operação em área compartilhada com pedestres, pontos cegos ou grande fluxo.', 'Lesões graves ou morte.', 'Separar pedestres e veículos; sinalizar; usar alertas sonoros e visuais; interromper manobra se a rota não estiver livre.'),
  ('ACIDENTE'::"RiskCategory", 'Tombamento ou capotamento', 'Curvas, velocidade incompatível, rampas, piso irregular, carga elevada ou instável.', 'Esmagamento, fraturas, lesões graves ou morte.', 'Respeitar capacidade e condições do equipamento; reduzir velocidade; transportar carga baixa; usar cinto quando disponível.'),
  ('ACIDENTE'::"RiskCategory", 'Queda ou deslocamento da carga', 'Carga instável, palete danificado, garfos mal posicionados ou excesso de peso.', 'Impacto, esmagamento e danos materiais.', 'Conferir carga e palete; respeitar capacidade indicada; estabilizar carga; manter visibilidade ou seguir procedimento seguro.'),
  ('ACIDENTE'::"RiskCategory", 'Prensagem ou aprisionamento', 'Manobras junto a estruturas, estantes, docas, cargas ou outros equipamentos.', 'Lesões, fraturas ou esmagamento.', 'Manter distância; planejar manobras; impedir pessoas na zona de risco; usar comunicação definida.'),
  ('ACIDENTE'::"RiskCategory", 'Queda por diferença de nível / escorregamento', 'Acesso ao equipamento, rampas, docas, desníveis, piso molhado, oleoso ou com obstáculos.', 'Entorses, contusões e fraturas.', 'Manter pisos e degraus limpos e conservados; remover obstáculos; usar pontos de apoio e calçado apropriado.'),
  ('ACIDENTE'::"RiskCategory", 'Falha mecânica ou perda de controle', 'Defeitos em freios, direção, pneus, garfos, mastro, buzina, alarmes ou dispositivos de segurança.', 'Colisão, tombamento, queda de carga ou atropelamento.', 'Inspecionar antes do uso; retirar equipamento defeituoso de operação; comunicar falhas e realizar manutenção.'),
  ('ACIDENTE'::"RiskCategory", 'Incêndio ou explosão', 'Abastecimento, vazamento de combustível, recarga de bateria ou fontes de ignição, conforme equipamento e local.', 'Queimaduras, intoxicação, lesões graves ou morte.', 'Seguir procedimento específico; controlar fontes de ignição; manter área adequada e recursos de emergência compatíveis.'),
  ('ACIDENTE'::"RiskCategory", 'Combustíveis ou inflamáveis', 'Armazenamento, abastecimento ou contato com combustível, quando aplicável.', 'Incêndio, queimaduras, intoxicação ou irritação, conforme a situação.', 'Armazenar e abastecer em local designado; controlar vazamentos; manter recipientes identificados e seguir procedimentos.'),
  ('ACIDENTE'::"RiskCategory", 'Choque elétrico ou arco elétrico', 'Recarga, manutenção ou troca de bateria elétrica, se tais tarefas forem realizadas.', 'Choque, queimaduras e lesões graves.', 'Restringir tarefas a pessoas autorizadas; seguir procedimento de bloqueio e recarga; manter cabos e conectores íntegros.'),
  ('ACIDENTE'::"RiskCategory", 'Iluminação ou sinalização inadequada', 'Áreas escuras, corredores sem sinalização ou ausência/falha de alertas do equipamento.', 'Colisões, atropelamentos e erros de manobra.', 'Manter iluminação e sinalização adequadas; verificar alarmes e dispositivos antes da operação.'),
  ('ACIDENTE'::"RiskCategory", 'Armazenamento inadequado', 'Pilhas instáveis, estruturas danificadas ou cargas armazenadas incorretamente.', 'Queda de materiais, esmagamento e danos.', 'Respeitar capacidade e estabilidade das estruturas; manter corredores livres; comunicar danos e bloquear áreas inseguras.'),
  ('ACIDENTE'::"RiskCategory", 'Calibração ou enchimento de pneus', 'Inflação de pneus realizada pelo operador, se aplicável.', 'Ruptura do pneu e projeção de componentes, com possibilidade de lesão grave.', 'Atribuir a pessoal capacitado; seguir instruções do fabricante e procedimento seguro; não permanecer na zona de projeção.'),
  ('ACIDENTE'::"RiskCategory", 'Animais peçonhentos ou insetos', 'Presença identificada em áreas externas, depósitos ou locais de armazenamento.', 'Picadas, alergias ou intoxicação, conforme o animal.', 'Manter limpeza e controle de pragas; inspecionar áreas; comunicar presença e seguir procedimento de resposta.')
) AS b("category","name","fonte","danos","medidas")
WHERE NOT EXISTS (
  SELECT 1 FROM "hazards" h WHERE h."tenantId" = t."id" AND lower(h."name") = lower(b."name") AND h."deletedAt" IS NULL
);
